import streamlit as st
st.set_page_config(page_title="Koncept AI - Premium eBook Studio", page_icon="\U0001F4DA", layout="wide", initial_sidebar_state="expanded")
import os, hashlib, traceback

def _safe_env(k):
    try:
        v = st.secrets.get(k, "")
        return v if v else os.getenv(k, "")
    except Exception:
        return os.getenv(k, "")

@st.cache_resource(show_spinner=False)
def get_groq():
    try:
        from groq import Groq
        key = _safe_env("GROQ_API_KEY")
        return Groq(api_key=key) if key else None
    except Exception:
        return None

@st.cache_resource(show_spinner=False)
def get_sb():
    try:
        url = _safe_env("SUPABASE_URL"); key = _safe_env("SUPABASE_KEY")
        if not url or not key: return None
        from supabase import create_client
        return create_client(url, key)
    except Exception:
        return None

def _hash(pw):
    try: return hashlib.sha256(str(pw).encode("utf-8")).hexdigest()
    except Exception: return ""

def _reraise_if_st_control(e):
    """Never swallow Streamlit's own control-flow exceptions (st.stop/st.rerun)."""
    if e.__class__.__name__ in ("StopException", "RerunException"):
        raise e

def _sanitize_pdf_text(s):
    rep = {"\u2014":"-","\u2013":"-","\u201c":'"',"\u201d":'"',"\u2018":"'","\u2019":"'","\u2026":"...","\u2022":"*","\u2713":"v","\u2605":"*","\u00a0":" "}
    for k, v in rep.items(): s = s.replace(k, v)
    return s.encode("latin-1", "replace").decode("latin-1")

