ADMIN_EMAIL = (_safe_env("ADMIN_EMAIL") or "admin@koncept.ai").strip().lower()
ADMIN_HASH = _hash(_safe_env("ADMIN_PASSWORD") or "admin123")

def is_admin():
    try: return bool(st.session_state["auth"].get("is_admin", False))
    except Exception: return False

def cur_user():
    try:
        a = st.session_state.get("auth", {})
        if not a.get("logged_in"): return None
        if a.get("is_admin"): return {"name":"Admin","tier":"Pro Max","email":ADMIN_EMAIL,"usage":{"books":0}}
        u = st.session_state.get("users", {}).get(a.get("email"))
        if isinstance(u, dict) and "usage" not in u: u["usage"]={"books":0}
        return u
    except Exception: return None

